	router.GET(options.BaseURL+"/admin/namespaces", wrapper.ListNamespaces)
	router.GET(options.BaseURL+"/admin/sandbox-templates", wrapper.AdminListSandboxTemplates)
	router.POST(options.BaseURL+"/admin/sandbox-templates", wrapper.AdminCreateSandboxTemplate)
	router.DELETE(options.BaseURL+"/admin/sandbox-templates/:name", wrapper.AdminDeleteSandboxTemplate)
	router.PUT(options.BaseURL+"/admin/sandbox-templates/:name", wrapper.AdminUpdateSandboxTemplate)
	router.GET(options.BaseURL+"/admin/statistics/sandboxes", wrapper.AdminGetSandboxStatistics)
	router.GET(options.BaseURL+"/admin/teams", wrapper.ListTeams)
	router.GET(options.BaseURL+"/admin/teams/:team/users", wrapper.ListUsersByTeam)
	router.GET(options.BaseURL+"/api-keys", wrapper.SelfListAPIKeys)
	router.POST(options.BaseURL+"/api-keys", wrapper.SelfCreateAPIKey)
	router.DELETE(options.BaseURL+"/api-keys/:name", wrapper.SelfDeleteAPIKey)
	router.GET(options.BaseURL+"/auth/whoami", wrapper.GetWhoAmI)
	router.GET(options.BaseURL+"/clusters", wrapper.ListClusters)
	router.GET(options.BaseURL+"/envs", wrapper.ListSandboxEnvs)
	router.POST(options.BaseURL+"/envs", wrapper.CreateSandboxEnv)
	router.DELETE(options.BaseURL+"/envs/:name", wrapper.DeleteSandboxEnv)
	router.GET(options.BaseURL+"/envs/:name", wrapper.GetSandboxEnv)
